import{_ as t,o as a,c as o,a4 as n}from"./chunks/framework.DCsBdTIw.js";const u=JSON.parse('{"title":"About Tokeness","description":"Tokeness is an AI API gateway that provides OpenAI-compatible access to multiple AI models, with API key management, quota control, and usage logging.","frontmatter":{"title":"About Tokeness","description":"Tokeness is an AI API gateway that provides OpenAI-compatible access to multiple AI models, with API key management, quota control, and usage logging.","head":[["script",{"type":"application/ld+json"},"{\\n  \\"@context\\": \\"https://schema.org\\",\\n  \\"@type\\": \\"SoftwareApplication\\",\\n  \\"name\\": \\"Tokeness\\",\\n  \\"applicationCategory\\": \\"DeveloperApplication\\",\\n  \\"operatingSystem\\": \\"Any\\",\\n  \\"url\\": \\"https://tokeness.io\\",\\n  \\"description\\": \\"Tokeness is an AI API gateway providing OpenAI-compatible access to multiple AI models, with API key management, quota control, and usage logging.\\",\\n  \\"offers\\": {\\n    \\"@type\\": \\"Offer\\",\\n    \\"priceCurrency\\": \\"CNY\\",\\n    \\"description\\": \\"Pre-paid, pay-per-token pricing. See the Tokeness console for current model prices.\\"\\n  },\\n  \\"provider\\": {\\n    \\"@type\\": \\"Organization\\",\\n    \\"name\\": \\"Tokeness\\",\\n    \\"url\\": \\"https://tokeness.io\\"\\n  }\\n}\\n"]]},"headers":[],"relativePath":"about.md","filePath":"about.md","lastUpdated":1784332800000}'),s={name:"about.md"};function i(r,e,d,l,c,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="about-tokeness" tabindex="-1">About Tokeness <a class="header-anchor" href="#about-tokeness" aria-label="Permalink to &quot;About Tokeness&quot;">​</a></h1><p>Tokeness is an AI API gateway for developers. You use one API key and a unified endpoint to call different AI models, then review balance, logs, and usage in the console.</p><h2 id="product-positioning" tabindex="-1">Product Positioning <a class="header-anchor" href="#product-positioning" aria-label="Permalink to &quot;Product Positioning&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Product type</td><td>AI API gateway</td></tr><tr><td>Standard Base URL</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>Common protocols</td><td>OpenAI Compatible API, OpenAI Responses API, Anthropic API</td></tr><tr><td>Console</td><td><a href="https://tokeness.io" target="_blank" rel="noreferrer">tokeness.io</a></td></tr><tr><td>Documentation</td><td><a href="https://docs.tokeness.io" target="_blank" rel="noreferrer">docs.tokeness.io</a></td></tr><tr><td>Billing model</td><td>Prepaid, deducted by actual usage</td></tr></tbody></table><h2 id="what-tokeness-solves" tabindex="-1">What Tokeness Solves <a class="header-anchor" href="#what-tokeness-solves" aria-label="Permalink to &quot;What Tokeness Solves&quot;">​</a></h2><p>Tokeness brings model access, key management, quota control, and usage tracking together in one console. For developers, integration typically only requires configuring the Base URL, API key, and model name; business code continues to call the OpenAI-compatible API as usual.</p><p>Common use cases include:</p><ul><li>Accessing multiple model providers with a single API key.</li><li>Creating separate API keys for development, production, and customer projects.</li><li>Reviewing call logs, balance, and consumption in the console.</li><li>Letting tools that support a custom OpenAI Base URL connect to Tokeness.</li></ul><h2 id="integration-facts" tabindex="-1">Integration Facts <a class="header-anchor" href="#integration-facts" aria-label="Permalink to &quot;Integration Facts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Question</th><th>Official answer</th></tr></thead><tbody><tr><td>What is the OpenAI-compatible endpoint?</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>Where are API keys created?</td><td>Tokeness console, API Keys page</td></tr><tr><td>Where are model names copied from?</td><td>Tokeness console or model marketplace</td></tr><tr><td>Where are prices authoritative?</td><td>Console model marketplace or formal quotation</td></tr><tr><td>Where are call records visible?</td><td>Usage logs and dashboard in the console</td></tr></tbody></table><h2 id="supported-integration-methods" tabindex="-1">Supported Integration Methods <a class="header-anchor" href="#supported-integration-methods" aria-label="Permalink to &quot;Supported Integration Methods&quot;">​</a></h2><p>Tokeness supports any client or SDK that allows a custom OpenAI Base URL. The documentation site provides integration guides for:</p><ul><li><a href="/integrations/openai-compatible">OpenAI Compatible API</a></li><li><a href="/integrations/openai-responses">OpenAI Responses API</a></li><li><a href="/integrations/anthropic-api">Anthropic API</a></li><li><a href="/integrations/custom-api-key">Custom API and Key</a></li><li><a href="/integrations/claude-code">Claude Code</a></li><li><a href="/integrations/cursor">Cursor</a></li><li><a href="/integrations/codex-cli">Codex CLI</a></li><li><a href="/integrations/dify">Dify</a></li><li><a href="/integrations/n8n">n8n</a></li><li><a href="/integrations/open-webui">Open WebUI</a></li></ul><h2 id="billing-and-usage" tabindex="-1">Billing and Usage <a class="header-anchor" href="#billing-and-usage" aria-label="Permalink to &quot;Billing and Usage&quot;">​</a></h2><p>Tokeness uses a prepaid model. Each API call is deducted by actual consumption; specific model prices are authoritative in the console. Public documentation only describes the billing approach and does not commit to fixed prices.</p><p>Cost-control tips: use a separate key for each project, set a small quota for development and testing, validate high-consumption tasks with a small sample first, and review usage logs and the dashboard regularly.</p><h2 id="official-links" tabindex="-1">Official Links <a class="header-anchor" href="#official-links" aria-label="Permalink to &quot;Official Links&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Entry</th><th>URL</th></tr></thead><tbody><tr><td>Website and console</td><td><a href="https://tokeness.io" target="_blank" rel="noreferrer">https://tokeness.io</a></td></tr><tr><td>Documentation</td><td><a href="https://docs.tokeness.io" target="_blank" rel="noreferrer">https://docs.tokeness.io</a></td></tr><tr><td>API Base URL</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>Contact</td><td><a href="mailto:contact@tokeness.io" target="_blank" rel="noreferrer">contact@tokeness.io</a></td></tr></tbody></table>',18)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
